using System.Text.Json.Nodes;
using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils.Interface;
namespace Tests;
public class AdminSearchTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Quick_find_is_permission_filtered_masked_multiterm_and_literal()
    {
        var admin=await Admin();var user=await LoginPhone("9884001234","Synthetic Search Customer");await ApiFactory.DbExecAsync("UPDATE users SET email='synthetic@example.test' WHERE id=@uid",new{uid=user.Id});
        Assert.Equal(403,(await user.Get("/api/admin/search?q=synthetic")).Status);Assert.Equal(403,(await user.Get("/api/admin/me")).Status);Assert.Empty((await admin.Get("/api/admin/search?q=x")).Json["results"]!.AsArray());
        var r=await admin.Get("/api/admin/search?q=Synthetic%20%20Customer");Assert.True(r.Status==200,r.ToString());Assert.Equal("Synthetic Customer",r.Json["q"]!.GetValue<string>());var found=r.Json["results"]!.AsArray().Single(x=>x!["id"]!.GetValue<string>()==user.Id)!;Assert.Equal("customer",found["kind"]!.GetValue<string>());Assert.Equal("•••• 1234 · s•••@example.test",found["sub"]!.GetValue<string>());Assert.Equal("/admin/customers/"+user.Id,found["href"]!.GetValue<string>());Assert.DoesNotContain("9884001234",r.Json.ToJsonString());
        Assert.Empty((await admin.Get("/api/admin/search?q=%25")).Json["results"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/search?q=zz%25")).Json["results"]!.AsArray());
        var catalog=await Staff(admin,"searchcatalog@example.test","catalog");Assert.Empty((await catalog.Get("/api/admin/search?q=Synthetic")).Json["results"]!.AsArray());Assert.Empty((await catalog.Get("/api/admin/search?q="+user.Id)).Json["results"]!.AsArray());
        r=await admin.Get("/api/admin/search?q="+user.Id);Assert.Equal("•••• 1234",r.Json["results"]![0]!["sub"]!.GetValue<string>());Assert.Equal(422,(await admin.Get("/api/admin/search?q="+new string('a',81))).Status);
        for(var i=0;i<6;i++)await ApiFactory.DbExecAsync("INSERT INTO users(id,name,phone,is_admin,is_active,ui_prefs)VALUES(@id,@name,@phone,0,1,'{}')",new{id=Guid.NewGuid(),name="Synthetic Limit Customer "+i,phone="988400000"+i});Assert.Equal(5,(await admin.Get("/api/admin/search?q=Synthetic%20Limit")).Json["results"]!.AsArray().Count);
        var seller=(await user.Post("/api/seller/register",new{display_name="Synthetic Search Store"})).Json["id"]!.GetValue<string>();Assert.DoesNotContain((await admin.Get("/api/admin/search?q=Synthetic%20Customer")).Json["results"]!.AsArray(),x=>x!["kind"]!.GetValue<string>()=="customer"&&x["id"]!.GetValue<string>()==user.Id);Assert.Equal("customer",(await admin.Get("/api/admin/search?q="+user.Id)).Json["results"]![0]!["kind"]!.GetValue<string>());
        await ApiFactory.DbExecAsync("UPDATE sellers SET display_name='Synthetic_100% Store' WHERE id=@seller",new{seller});Assert.Single((await admin.Get("/api/admin/search?q=Synthetic_100%25")).Json["results"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/search?q=Synthetic_200%25")).Json["results"]!.AsArray());

        var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Synthetic Search','synthetic-search','',1000,500,0,1,'[]')",new{cat});var product=(await user.Post("/api/seller/products",new{category_id=cat,title="Synthetic Search Product",hsn_code="6205",gst_bps=500,variants=new[]{new{sku="UNIQUE-SEARCH-SKU",mrp_paise=20000,price_paise=10000,stock=10}}})).Json;var pid=product["id"]!.GetValue<string>();
        Assert.Equal("product",(await catalog.Get("/api/admin/search?q=UNIQUE-SEARCH-SKU")).Json["results"]![0]!["kind"]!.GetValue<string>());
        using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var orders=scope.ServiceProvider.GetRequiredService<OrdersDAL>();var ledger=scope.ServiceProvider.GetRequiredService<LedgerDAL>();var delivery=scope.ServiceProvider.GetRequiredService<DeliveryDAL>();var oid=Guid.NewGuid();var payout=Guid.NewGuid();var partner=Guid.NewGuid();var ticket=Guid.NewGuid();
        await delivery.InsertPartnerAsync(new(){Id=partner,UserId=Guid.Parse(user.Id),Name="Synthetic Search Partner",Phone="9884001234",VehicleType="bike",KycStatus="draft",BankDetails="{}",CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow});
        await using(var tx=await db.BeginAsync()){await orders.InsertOrderAsync(new(){Id=oid,Number="SYNTH-SEARCH-ORDER",UserId=Guid.Parse(user.Id),Status="placed",PaymentMethod="cod",PaymentStatus="cod",ShipTo="{}",ItemsTotal=12345,GrandTotal=12345,Currency="INR",FxRate=1,Fees="[]",IdempotencyKey=Guid.NewGuid().ToString(),CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow},tx);await ledger.InsertPayoutAsync(new(){Id=payout,SellerId=Guid.Parse(seller),Number="SYNTH-SEARCH-PAYOUT",Amount=12345,Status="pending",Mode="manual",BankSnapshot="{}",CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow},tx);await tx.CommitAsync();}
        await ApiFactory.DbExecAsync("INSERT INTO support_tickets(id,number,user_id,category,subject,status,priority,is_grievance,ack_due_at,resolve_due_at)VALUES(@ticket,'SYNTH-SEARCH-TICKET',@uid,'other','Synthetic Search Support','open','normal',0,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6))",new{ticket,uid=user.Id});
        foreach(var(kind,term,rid)in new[]{("order","SYNTH-SEARCH-ORDER",oid.ToString()),("product","UNIQUE-SEARCH-SKU",pid),("partner","Synthetic Search Partner",partner.ToString()),("ticket","SYNTH-SEARCH-TICKET",ticket.ToString()),("payout","SYNTH-SEARCH-PAYOUT",payout.ToString()),("seller","Synthetic_100% Store",seller)})
        {var q=Uri.EscapeDataString(term);r=await admin.Get("/api/admin/search?q="+q);Assert.Contains(r.Json["results"]!.AsArray(),x=>x!["kind"]!.GetValue<string>()==kind&&x["id"]!.GetValue<string>()==rid);Assert.Contains((await admin.Get("/api/admin/search?q="+rid)).Json["results"]!.AsArray(),x=>x!["kind"]!.GetValue<string>()==kind);}
        Assert.Contains("₹123.45",(await admin.Get("/api/admin/search?q=SYNTH-SEARCH-ORDER")).Json["results"]![0]!["sub"]!.GetValue<string>());Assert.Empty((await catalog.Get("/api/admin/search?q=SYNTH-SEARCH-PAYOUT")).Json["results"]!.AsArray());
        r=await admin.Get("/api/admin/me");Assert.Equal("owner",r.Json["role"]!.GetValue<string>());Assert.True(r.Json["is_owner"]!.GetValue<bool>());Assert.False(r.Json["two_step_required"]!.GetValue<bool>());
        await ApiFactory.DbExecAsync("INSERT INTO platform_settings(`key`,value,updated_at)VALUES('auth','{\"staff_require_two_step\":true}',UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE value=VALUES(value)");Assert.Equal(200,(await admin.Get("/api/admin/me")).Status);Assert.True((await admin.Get("/api/admin/me")).Json["two_step_required"]!.GetValue<bool>());
    }
}
